package com.crm.identity.service;
import com.crm.identity.repository.*;import com.crm.identity.entity.User;import com.crm.identity.exception.InvalidCredentialsException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import jakarta.validation.constraints.*;
@Service @Transactional public class PasswordLifecycleService {
 public record Input(@NotBlank @Size(max=190) String login,@NotBlank @Size(max=100) String currentPassword,@NotBlank @Size(min=6,max=100) String newPassword){@Override public String toString(){return "PasswordChangeInput[REDACTED]";}}
 private final UserRepository users;private final RefreshTokenRepository sessions;private final PasswordEncoder encoder;private final jakarta.persistence.EntityManager em;private final AdministrationJournal journal;
 public PasswordLifecycleService(UserRepository u,RefreshTokenRepository s,PasswordEncoder p,jakarta.persistence.EntityManager e,AdministrationJournal j){users=u;sessions=s;encoder=p;em=e;journal=j;}
 public void change(Input input){try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){if(input==null||!factory.getValidator().validate(input).isEmpty()||input.newPassword().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Invalid password change input");}var found=input.login().contains("@")?users.findByEmail(input.login()):users.findByUsername(input.login());User user=found.flatMap(u->users.lockById(u.getId())).orElseThrow(this::invalid);em.refresh(user,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);if(!user.isEnabled()||!user.isAccountNonLocked()||!encoder.matches(input.currentPassword(),user.getPassword()))throw invalid();if(encoder.matches(input.newPassword(),user.getPassword()))throw new IllegalArgumentException("New password must differ");user.setPassword(encoder.encode(input.newPassword()));user.setPasswordChangeRequired(false);sessions.revokeAllByUser(user);journal.record(user,user.getId(),"PASSWORD_CHANGED");}
 private InvalidCredentialsException invalid(){return new InvalidCredentialsException("Invalid credentials");}
}
